import { Fragment, useEffect, useRef, useState } from "react";
import {
  Stage,
  Layer,
  Image as KonvaImage,
  Line,
  Rect,
  Circle as KonvaCircle,
  Text as KonvaText,
  Transformer,
} from "react-konva";
import type { KonvaEventObject } from "konva/lib/Node";
import type { Node as KonvaNode } from "konva/lib/Node";
import type { Transformer as KonvaTransformer } from "konva/lib/shapes/Transformer";
import { Modal, Input, InputNumber, Button, Space } from "antd";
import { DeleteOutlined } from "@ant-design/icons";
import { useRiskMappingWorkbenchStore } from "@/store/riskMappingWorkbenchStore";
import {
  clampPoint,
  cubicBezierPoints,
  ellipsePoints,
  pointsToKonva,
  polygonCentroid,
  toCanvasX,
  toCanvasY,
  toPercent,
} from "@/utils/riskMappingGeometry";
import type { PendingRegion, RiskPolygonPoint, RiskCanvasText, WorkbenchZone } from "@/types/riskMappingWorkbench";
import type { RiskObject } from "@/types/riskManagement";
import { zoneDisplayColor } from "@/utils/zoneDisplay";
import { collectRegionsInRect, rectFromPoints } from "@/utils/riskMappingMarquee";
import WorkbenchRiskPointLayer from "./WorkbenchRiskPointLayer";

const STAGE_WIDTH = 1200;
const STAGE_HEIGHT = 900;

interface LoadedImage {
  url: string;
  image: HTMLImageElement;
}

interface PenAnchor {
  point: RiskPolygonPoint;
  handle: RiskPolygonPoint | null;
}

const samePoint = (a: RiskPolygonPoint, b: RiskPolygonPoint) => a.x === b.x && a.y === b.y;

const dedupeTail = (points: RiskPolygonPoint[]) => {
  const out = [...points];
  while (out.length > 1 && samePoint(out[out.length - 1], out[out.length - 2])) out.pop();
  return out;
};

const nextLocalId = (prefix: string) => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

const mirrorHandle = (point: RiskPolygonPoint, handle: RiskPolygonPoint): RiskPolygonPoint => ({
  x: point.x * 2 - handle.x,
  y: point.y * 2 - handle.y,
});

const samplePenAnchors = (anchors: PenAnchor[], closed = false): RiskPolygonPoint[] | null => {
  if (anchors.length < 2) return null;
  const points: RiskPolygonPoint[] = [anchors[0].point];
  const appendSegment = (start: PenAnchor, end: PenAnchor) => {
    const cp1 = start.handle ?? start.point;
    const cp2 = end.handle ? mirrorHandle(end.point, end.handle) : end.point;
    const sampled = cubicBezierPoints(start.point, cp1, cp2, end.point, 24).slice(1);
    points.push(...sampled);
  };
  for (let i = 0; i < anchors.length - 1; i++) {
    appendSegment(anchors[i], anchors[i + 1]);
  }
  if (closed && anchors.length >= 3) {
    appendSegment(anchors[anchors.length - 1], anchors[0]);
  }
  return points;
};

const isEditableTarget = (target: Element | null) => {
  if (!target) return false;
  const tag = target.tagName;
  return tag === "INPUT" || tag === "TEXTAREA" || (target as HTMLElement).isContentEditable;
};

export default function WorkbenchCanvas({ colorMode = "current" }: { colorMode?: "current" | "inherent" }) {
  const zones = useRiskMappingWorkbenchStore(s => s.zones);
  const pendingRegions = useRiskMappingWorkbenchStore(s => s.pendingRegions);
  const texts = useRiskMappingWorkbenchStore(s => s.texts);
  const riskPoints = useRiskMappingWorkbenchStore(s => s.riskPoints);
  const tool = useRiskMappingWorkbenchStore(s => s.tool);
  const gridEnabled = useRiskMappingWorkbenchStore(s => s.gridEnabled);
  const snapEnabled = useRiskMappingWorkbenchStore(s => s.snapEnabled);
  const guideEnabled = useRiskMappingWorkbenchStore(s => s.guideEnabled);
  const showFloorPlan = useRiskMappingWorkbenchStore(s => s.showFloorPlan);
  const selectedRegionIds = useRiskMappingWorkbenchStore(s => s.selectedRegionIds);
  const selectedTextId = useRiskMappingWorkbenchStore(s => s.selectedTextId);
  const viewScale = useRiskMappingWorkbenchStore(s => s.viewScale);
  const viewX = useRiskMappingWorkbenchStore(s => s.viewX);
  const viewY = useRiskMappingWorkbenchStore(s => s.viewY);
  const floor = useRiskMappingWorkbenchStore(s => s.floors.find(f => f.id === s.currentFloorId));
  const currentFloorId = useRiskMappingWorkbenchStore(s => s.currentFloorId);
  const setState = useRiskMappingWorkbenchStore.setState;
  const setSnapshot = useRiskMappingWorkbenchStore.getState().setSnapshot;
  const commit = useRiskMappingWorkbenchStore.getState().commit;
  const [draftPoints, setDraftPointsState] = useState<RiskPolygonPoint[]>([]);
  const draftPointsRef = useRef<RiskPolygonPoint[]>([]);
  const setDraftPoints = (next: RiskPolygonPoint[] | ((prev: RiskPolygonPoint[]) => RiskPolygonPoint[])) => {
    const value = typeof next === "function" ? next(draftPointsRef.current) : next;
    draftPointsRef.current = value;
    setDraftPointsState(value);
  };
  const [penAnchors, setPenAnchorsState] = useState<PenAnchor[]>([]);
  const penAnchorsRef = useRef<PenAnchor[]>([]);
  const setPenAnchors = (next: PenAnchor[] | ((prev: PenAnchor[]) => PenAnchor[])) => {
    const value = typeof next === "function" ? next(penAnchorsRef.current) : next;
    penAnchorsRef.current = value;
    setPenAnchorsState(value);
  };
  const [penActive, setPenActiveState] = useState<PenAnchor | null>(null);
  const penActiveRef = useRef<PenAnchor | null>(null);
  const setPenActive = (next: PenAnchor | null) => {
    penActiveRef.current = next;
    setPenActiveState(next);
  };
  const [draftCursor, setDraftCursor] = useState<RiskPolygonPoint | null>(null);
  const [draftStart, setDraftStart] = useState<RiskPolygonPoint | null>(null);
  const [draftEnd, setDraftEnd] = useState<RiskPolygonPoint | null>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [loadedImage, setLoadedImage] = useState<LoadedImage | null>(null);
  const [editingTextId, setEditingTextId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState("");
  const [editFontSize, setEditFontSize] = useState(14);
  const [editColor, setEditColor] = useState("#333333");
  const pendingDragOriginRef = useRef<Map<string, RiskPolygonPoint[]>>(new Map());
  const regionNodeRefs = useRef<Map<string, KonvaNode>>(new Map());
  const regionTransformOriginRef = useRef<Map<string, RiskPolygonPoint[]>>(new Map());
  const groupDragRef = useRef<{ startX: number; startY: number; origin: Map<string, RiskPolygonPoint[]> } | null>(null);
  const dragWritebackRef = useRef(false);
  const transformerRef = useRef<KonvaTransformer>(null);
  const spacePressedRef = useRef(false);
  const panStartRef = useRef<{ x: number; y: number; viewX: number; viewY: number } | null>(null);
  const isPanningRef = useRef(false);
  const penDraggedRef = useRef(false);
  const penCloseCandidateRef = useRef(false);
  const [isPanning, setIsPanning] = useState(false);
  const [spacePressed, setSpacePressed] = useState(false);
  const canvasBoxRef = useRef<HTMLDivElement | null>(null);
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });
  const [marqueeStart, setMarqueeStart] = useState<RiskPolygonPoint | null>(null);
  const [marqueeEnd, setMarqueeEnd] = useState<RiskPolygonPoint | null>(null);
  const marqueeEndRef = useRef<RiskPolygonPoint | null>(null);
  const marqueeShiftRef = useRef(false);
  const zoneColor = (z: WorkbenchZone) => zoneDisplayColor(z, colorMode);

  useEffect(() => {
    const url = floor?.floor_plan_url;
    if (!url) return;
    const img = new window.Image();
    img.onload = () => setLoadedImage({ url, image: img });
    img.src = url;
    return () => {
      img.onload = null;
    };
  }, [floor?.floor_plan_url]);

  useEffect(() => {
    const el = canvasBoxRef.current;
    if (!el) return;
    const update = () => setContainerSize({ width: el.clientWidth, height: el.clientHeight });
    update();
    const observer = new ResizeObserver(update);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!["polygon", "pen", "freehand"].includes(tool)) {
      setDraftPoints([]);
      setDraftCursor(null);
      setDraftStart(null);
      setDraftEnd(null);
      setIsDrawing(false);
    }
    if (tool !== "pen") {
      setPenAnchors([]);
      setPenActive(null);
      penCloseCandidateRef.current = false;
    }
  }, [tool]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.code === "Space" && !isEditableTarget(document.activeElement)) {
        event.preventDefault();
        spacePressedRef.current = true;
        setSpacePressed(true);
      }
      if (event.key === "Escape") {
        setDraftPoints([]);
        setDraftCursor(null);
        setDraftStart(null);
        setDraftEnd(null);
        penCloseCandidateRef.current = false;
        setPenAnchors([]);
        setPenActive(null);
        setIsDrawing(false);
        setState({ selectedRegionIds: [], selectedRiskPointId: null, selectedTextId: null });
        return;
      }
      if (event.key === "Enter" && ["polygon", "pen"].includes(useRiskMappingWorkbenchStore.getState().tool)) {
        event.preventDefault();
        finishDrawing();
        return;
      }
      if ((event.key === "Delete" || event.key === "Backspace") && !isEditableTarget(document.activeElement)) {
        useRiskMappingWorkbenchStore.getState().deleteSelected();
      }
    };
    const onKeyUp = (event: KeyboardEvent) => {
      if (event.code === "Space") {
        spacePressedRef.current = false;
        setSpacePressed(false);
      }
    };
    const onWindowMouseMove = (event: MouseEvent) => {
      if (!isPanningRef.current || !panStartRef.current) return;
      const origin = panStartRef.current;
      setState({
        viewX: origin.viewX + event.clientX - origin.x,
        viewY: origin.viewY + event.clientY - origin.y,
      });
    };
    const onWindowMouseUp = () => {
      if (isPanningRef.current) {
        isPanningRef.current = false;
        setIsPanning(false);
        panStartRef.current = null;
      }
    };
    const onWindowMouseDown = (event: MouseEvent) => {
      const target = event.target as HTMLElement | null;
      const canvasContainer = document.querySelector('[data-testid="workbench-canvas"]');
      if (!target || !canvasContainer?.contains(target)) return;
      if (event.button === 2 || (event.button === 0 && spacePressedRef.current)) {
        event.preventDefault();
        const view = useRiskMappingWorkbenchStore.getState();
        panStartRef.current = { x: event.clientX, y: event.clientY, viewX: view.viewX, viewY: view.viewY };
        isPanningRef.current = true;
        setIsPanning(true);
      }
    };
    const onFinishDrawing = () => finishDrawing();
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("keyup", onKeyUp);
    window.addEventListener("mousedown", onWindowMouseDown);
    window.addEventListener("mousemove", onWindowMouseMove);
    window.addEventListener("mouseup", onWindowMouseUp);
    window.addEventListener("risk-mapping:finish-drawing", onFinishDrawing);
    return () => {
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("keyup", onKeyUp);
      window.removeEventListener("mousedown", onWindowMouseDown);
      window.removeEventListener("mousemove", onWindowMouseMove);
      window.removeEventListener("mouseup", onWindowMouseUp);
      window.removeEventListener("risk-mapping:finish-drawing", onFinishDrawing);
    };
  }, [setState]);

  const image = loadedImage && loadedImage.url === floor?.floor_plan_url ? loadedImage.image : null;
  const canvasWidth = floor?.canvas_width || (image ? image.naturalWidth : STAGE_WIDTH);
  const canvasHeight = floor?.canvas_height || (image ? image.naturalHeight : STAGE_HEIGHT);

  // 画布尺寸或容器变化时自动适配视图（导入后画布更换也能铺满容器）
  useEffect(() => {
    if (!containerSize.width || !containerSize.height) return;
    const scale = Math.min(4, Math.max(0.25, Math.min(
      containerSize.width / canvasWidth,
      containerSize.height / canvasHeight,
    )));
    const x = (containerSize.width - canvasWidth * scale) / 2;
    const y = (containerSize.height - canvasHeight * scale) / 2;
    useRiskMappingWorkbenchStore.setState({ viewScale: scale, viewX: x, viewY: y });
  }, [canvasWidth, canvasHeight, containerSize.width, containerSize.height]);

  const pointFromEvent = (e: KonvaEventObject<MouseEvent>): RiskPolygonPoint => {
    const stage = e.target.getStage?.() ?? null;
    const pos = stage?.getPointerPosition?.() ?? null;
    const rawX = pos ? (pos.x - viewX) / viewScale : (e.evt.offsetX ?? 0);
    const rawY = pos ? (pos.y - viewY) / viewScale : (e.evt.offsetY ?? 0);
    const rounded = (v: number) => (snapEnabled ? Math.round(v / 5) * 5 : Math.round(v * 100) / 100);
    return {
      x: Math.min(100, Math.max(0, rounded(toPercent(rawX, canvasWidth)))),
      y: Math.min(100, Math.max(0, rounded(toPercent(rawY, canvasHeight)))),
    };
  };

  // 框选使用不做网格吸附的坐标：绘制工具的 5% 吸附会把小范围框选压缩成 0 尺寸。
  const rawPointFromEvent = (e: KonvaEventObject<MouseEvent>): RiskPolygonPoint => {
    const stage = e.target.getStage?.() ?? null;
    const pos = stage?.getPointerPosition?.() ?? null;
    const rawX = pos ? (pos.x - viewX) / viewScale : (e.evt.offsetX ?? 0);
    const rawY = pos ? (pos.y - viewY) / viewScale : (e.evt.offsetY ?? 0);
    return {
      x: Math.min(100, Math.max(0, Math.round(toPercent(rawX, canvasWidth) * 100) / 100)),
      y: Math.min(100, Math.max(0, Math.round(toPercent(rawY, canvasHeight) * 100) / 100)),
    };
  };

  const addPending = (points: RiskPolygonPoint[]) => {
    const region = {
      id: nextLocalId("pending"),
      floor_id: currentFloorId,
      points,
      created_at: new Date().toISOString(),
    };
    commit();
    setSnapshot({ pendingRegions: [...useRiskMappingWorkbenchStore.getState().pendingRegions, region] });
    setState({ selectedRegionIds: [`pending:${region.id}`] });
  };

  const createRiskPoint = (p: RiskPolygonPoint) => {
    const riskPoint: RiskObject = {
      id: nextLocalId("new-point"),
      enterprise_id: "",
      zone_id: null,
      floor_id: currentFloorId,
      name: "新风险点",
      category: null,
      location: null,
      location_x: p.x,
      location_y: p.y,
      description: null,
      image_url: null,
      responsible_unit: null,
      responsible_person: null,
      contact_phone: null,
      is_risk_point: true,
      sort_order: riskPoints.length,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      unit_count: 0,
    };
    commit();
    setSnapshot({ riskPoints: [...useRiskMappingWorkbenchStore.getState().riskPoints, riskPoint] });
    setState({ tool: "select", selectedRiskPointId: riskPoint.id });
  };

  const createText = (p: RiskPolygonPoint) => {
    const item: RiskCanvasText = {
      id: nextLocalId("text"),
      content: "新文字标注",
      x: p.x,
      y: p.y,
      font_size: 14,
      color: "#333333",
      rotation: 0,
      sort_order: texts.length,
    };
    commit();
    setSnapshot({ texts: [...useRiskMappingWorkbenchStore.getState().texts, item] });
    setEditingTextId(item.id);
    setEditContent(item.content);
    setEditFontSize(item.font_size);
    setEditColor(item.color);
    setState({ tool: "select", selectedTextId: item.id });
  };

  const handleClick = (e: KonvaEventObject<MouseEvent>) => {
    if (["select", "rect", "circle", "freehand"].includes(tool)) return;
    if (e.evt.detail > 1) return;
    const p = pointFromEvent(e);
    if (tool === "risk-point") {
      createRiskPoint(p);
      return;
    }
    if (tool === "text") {
      createText(p);
    }
  };

  const finishDrawing = () => {
    const activeTool = useRiskMappingWorkbenchStore.getState().tool;
    if (activeTool === "polygon" || activeTool === "freehand") {
      const cleaned = dedupeTail(draftPointsRef.current);
      if (cleaned.length >= 3) addPending(cleaned);
    }
    if (activeTool === "pen") {
      const sampled = samplePenAnchors(penAnchorsRef.current, true);
      if (sampled && sampled.length >= 3) addPending(sampled);
    }
    setDraftPoints([]);
    setDraftCursor(null);
    setDraftStart(null);
    setDraftEnd(null);
    setPenAnchors([]);
    setPenActive(null);
    penCloseCandidateRef.current = false;
    setIsDrawing(false);
  };

  const resolveRegionPoints = (id: string): RiskPolygonPoint[] | null => {
    const store = useRiskMappingWorkbenchStore.getState();
    if (id.startsWith("pending:")) {
      return store.pendingRegions.find(r => r.id === id.slice("pending:".length))?.points ?? null;
    }
    if (id.startsWith("zone:")) {
      const body = id.slice("zone:".length);
      const separator = body.indexOf(":");
      const zoneId = body.slice(0, separator);
      const polygonId = body.slice(separator + 1);
      const zone = store.zones.find(z => z.id === zoneId);
      return zone?.floor_plan_polygon?.polygons.find(p => p.id === polygonId)?.points ?? null;
    }
    return null;
  };

  const applyRegionPointUpdates = (
    zones: WorkbenchZone[],
    pendingRegions: PendingRegion[],
    updates: Map<string, RiskPolygonPoint[]>,
  ) => {
    const zoneUpdates = new Map<string, Map<string, RiskPolygonPoint[]>>();
    const pendingUpdates = new Map<string, RiskPolygonPoint[]>();
    updates.forEach((points, id) => {
      if (id.startsWith("pending:")) {
        pendingUpdates.set(id.slice("pending:".length), points);
      } else if (id.startsWith("zone:")) {
        const body = id.slice("zone:".length);
        const separator = body.indexOf(":");
        const zoneId = body.slice(0, separator);
        const polygonId = body.slice(separator + 1);
        if (!zoneUpdates.has(zoneId)) zoneUpdates.set(zoneId, new Map());
        zoneUpdates.get(zoneId)!.set(polygonId, points);
      }
    });
    return {
      zones: zones.map(z => {
        const map = zoneUpdates.get(z.id);
        if (!map || !z.floor_plan_polygon) return z;
        return {
          ...z,
          floor_plan_polygon: {
            ...z.floor_plan_polygon,
            polygons: z.floor_plan_polygon.polygons.map(p =>
              map.has(p.id) ? { ...p, points: map.get(p.id)! } : p,
            ),
          },
        };
      }),
      pendingRegions: pendingRegions.map(r =>
        pendingUpdates.has(r.id) ? { ...r, points: pendingUpdates.get(r.id)! } : r,
      ),
    };
  };

  const handleRegionTransformStart = (regionId: string, points: RiskPolygonPoint[]) => {
    const store = useRiskMappingWorkbenchStore.getState();
    const targets = store.selectedRegionIds.length ? store.selectedRegionIds : [regionId];
    regionTransformOriginRef.current.clear();
    targets.forEach(id => {
      const pts = resolveRegionPoints(id);
      if (pts) regionTransformOriginRef.current.set(id, pts);
    });
    if (!regionTransformOriginRef.current.size) {
      regionTransformOriginRef.current.set(regionId, points);
    }
  };

  const handleRegionTransformEnd = () => {
    const origin = regionTransformOriginRef.current;
    if (!origin.size) return;
    const updates = new Map<string, RiskPolygonPoint[]>();
    origin.forEach((points, id) => {
      const node = regionNodeRefs.current.get(id);
      if (!node) return;
      const transform = node.getTransform();
      const next = points.map(pt => {
        const canvasPoint = transform.point({
          x: toCanvasX(pt.x, canvasWidth),
          y: toCanvasY(pt.y, canvasHeight),
        });
        return clampPoint({
          x: toPercent(canvasPoint.x, canvasWidth),
          y: toPercent(canvasPoint.y, canvasHeight),
        });
      });
      node.scale({ x: 1, y: 1 });
      node.rotation(0);
      node.position({ x: 0, y: 0 });
      node.offset({ x: 0, y: 0 });
      updates.set(id, next);
    });
    regionTransformOriginRef.current.clear();
    if (!updates.size) return;
    const store = useRiskMappingWorkbenchStore.getState();
    const applied = applyRegionPointUpdates(store.zones, store.pendingRegions, updates);
    commit();
    setSnapshot(applied);
  };

  const handleMouseDown = (e: KonvaEventObject<MouseEvent>) => {
    if (e.evt.button === 2 || (e.evt.button === 0 && spacePressedRef.current)) {
      e.evt.preventDefault();
      const view = useRiskMappingWorkbenchStore.getState();
      panStartRef.current = { x: e.evt.clientX, y: e.evt.clientY, viewX: view.viewX, viewY: view.viewY };
      isPanningRef.current = true;
      setIsPanning(true);
      return;
    }
    if (e.evt.detail > 1) return;
    if (tool === "select") {
      const p = rawPointFromEvent(e);
      marqueeShiftRef.current = e.evt.shiftKey;
      marqueeEndRef.current = p;
      setMarqueeStart(p);
      setMarqueeEnd(p);
      return;
    }
    if (tool === "rect" || tool === "circle") {
      const p = pointFromEvent(e);
      setIsDrawing(true);
      setDraftStart(p);
      setDraftEnd(p);
      return;
    }
    if (tool === "polygon") {
      setDraftPoints(prev => [...prev, pointFromEvent(e)]);
      return;
    }
    if (tool === "pen") {
      const p = pointFromEvent(e);
      const nearFirst =
        penAnchors.length >= 3 &&
        Math.hypot(p.x - penAnchors[0].point.x, p.y - penAnchors[0].point.y) <= 3;
      const nearLast =
        penAnchors.length >= 3 &&
        Math.hypot(
          p.x - penAnchors[penAnchors.length - 1].point.x,
          p.y - penAnchors[penAnchors.length - 1].point.y,
        ) <= 3;
      if (nearFirst || nearLast) {
        penCloseCandidateRef.current = true;
        return;
      }
      setIsDrawing(true);
      penDraggedRef.current = false;
      setPenActive({ point: p, handle: null });
      return;
    }
    if (tool === "freehand") {
      setIsDrawing(true);
      setDraftPoints([pointFromEvent(e)]);
      return;
    }
  };

  const handleMouseMove = (e: KonvaEventObject<MouseEvent>) => {
    if (isPanningRef.current) return;
    if (marqueeStart) {
      const p = rawPointFromEvent(e);
      marqueeEndRef.current = p;
      setMarqueeEnd(p);
      return;
    }
    const p = pointFromEvent(e);
    if ((tool === "rect" || tool === "circle") && isDrawing) {
      setDraftEnd(p);
      return;
    }
    if (tool === "freehand" && isDrawing) {
      setDraftPoints(prev => [...prev, p]);
      return;
    }
    if (tool === "pen" && isDrawing) {
      if (penActiveRef.current) {
        const active = penActiveRef.current;
        if (Math.hypot(p.x - active.point.x, p.y - active.point.y) > 0.2) {
          penDraggedRef.current = true;
        }
        setPenActive({ point: active.point, handle: penDraggedRef.current ? p : null });
      }
      return;
    }
    if (tool === "polygon" && draftPoints.length > 0 && !isDrawing) {
      setDraftCursor(p);
    }
    if (tool === "pen" && penAnchors.length > 0 && !isDrawing) {
      setDraftCursor(p);
    }
  };

  const handleMouseUp = () => {
    if (isPanningRef.current) {
      isPanningRef.current = false;
      setIsPanning(false);
      panStartRef.current = null;
      return;
    }
    if (marqueeStart) {
      const end = marqueeEndRef.current ?? marqueeStart;
      const rect = rectFromPoints(marqueeStart, end, (3 / canvasWidth) * 100);
      const append = marqueeShiftRef.current;
      setMarqueeStart(null);
      setMarqueeEnd(null);
      marqueeEndRef.current = null;
      const store = useRiskMappingWorkbenchStore.getState();
      if (!rect) {
        if (!append) store.setSelectedRegions([]);
        return;
      }
      const hitIds: string[] = [];
      store.zones.forEach(z => {
        const polygons = z.floor_plan_polygon?.polygons ?? [];
        collectRegionsInRect(polygons, rect).forEach(pid => hitIds.push(`zone:${z.id}:${pid}`));
      });
      if (!hitIds.length) {
        if (!append) store.setSelectedRegions([]);
        return;
      }
      store.setSelectedRegions(hitIds, { append });
      const firstZoneId = hitIds[0].slice("zone:".length).split(":")[0];
      useRiskMappingWorkbenchStore.setState({ selectedZoneId: firstZoneId });
      return;
    }
    if (tool === "pen" && penCloseCandidateRef.current) {
      penCloseCandidateRef.current = false;
      finishDrawing();
      return;
    }
    if (tool === "rect" && isDrawing) {
      if (draftStart && draftEnd) {
        const x1 = Math.min(draftStart.x, draftEnd.x);
        const x2 = Math.max(draftStart.x, draftEnd.x);
        const y1 = Math.min(draftStart.y, draftEnd.y);
        const y2 = Math.max(draftStart.y, draftEnd.y);
        if (x2 - x1 >= 0.1 && y2 - y1 >= 0.1) {
          addPending([
            { x: x1, y: y1 },
            { x: x2, y: y1 },
            { x: x2, y: y2 },
            { x: x1, y: y2 },
          ]);
        }
      }
      setDraftStart(null);
      setDraftEnd(null);
      setIsDrawing(false);
      return;
    }
    if (tool === "circle" && isDrawing) {
      if (draftStart && draftEnd) {
        const radius = Math.hypot(
          toCanvasX(draftEnd.x, canvasWidth) - toCanvasX(draftStart.x, canvasWidth),
          toCanvasY(draftEnd.y, canvasHeight) - toCanvasY(draftStart.y, canvasHeight),
        );
        if (radius > 0.1) {
          addPending(
            ellipsePoints(
              draftStart,
              (radius / canvasWidth) * 100,
              (radius / canvasHeight) * 100,
            ),
          );
        }
      }
      setDraftStart(null);
      setDraftEnd(null);
      setIsDrawing(false);
      return;
    }
    if (tool === "freehand" && isDrawing) {
      if (draftPointsRef.current.length >= 3) {
        finishDrawing();
      } else {
        setDraftPoints([]);
        setIsDrawing(false);
      }
      return;
    }
    if (tool === "pen" && isDrawing) {
      if (penActiveRef.current) setPenAnchors(prev => [...prev, penActiveRef.current!]);
      penDraggedRef.current = false;
      setPenActive(null);
      setIsDrawing(false);
      setDraftStart(null);
      setDraftEnd(null);
    }
  };

  const handleWheel = (e: KonvaEventObject<WheelEvent>) => {
    const stage = e.target.getStage();
    if (!stage) return;
    e.evt.preventDefault();
    const pointer = stage.getPointerPosition();
    if (!pointer) return;
    const oldScale = viewScale;
    const mousePointTo = {
      x: (pointer.x - viewX) / oldScale,
      y: (pointer.y - viewY) / oldScale,
    };
    const direction = e.evt.deltaY > 0 ? 1 / 1.2 : 1.2;
    const nextScale = Math.min(4, Math.max(0.25, oldScale * direction));
    setState({
      viewScale: nextScale,
      viewX: pointer.x - mousePointTo.x * nextScale,
      viewY: pointer.y - mousePointTo.y * nextScale,
    });
  };

  const editingText = editingTextId ? texts.find(t => t.id === editingTextId) : null;
  const penPathPoints = samplePenAnchors(penAnchors);
  const penPreviewAnchors = penActive ? [...penAnchors, penActive] : penAnchors;
  const penPreviewPoints = penActive ? samplePenAnchors(penPreviewAnchors) : null;
  const penCursorPreview =
    !penActive && draftCursor && penAnchors.length > 0
      ? samplePenAnchors([penAnchors[penAnchors.length - 1], { point: draftCursor, handle: null }])
      : null;

  return (
    <>
      <div
        ref={canvasBoxRef}
        data-testid="workbench-canvas"
        data-draft-count={draftPoints.length}
        data-floor-plan={showFloorPlan}
        data-transform-active={tool === "select" && selectedRegionIds.length > 0}
        data-tool={tool}
        data-space={spacePressed}
        data-view-x={viewX}
        data-view-y={viewY}
        data-view-scale={viewScale}
        style={{ height: "100%" }}
        onMouseDownCapture={e => {
          if (e.button === 2 || (e.button === 0 && spacePressedRef.current)) {
            e.preventDefault();
            const view = useRiskMappingWorkbenchStore.getState();
            panStartRef.current = { x: e.clientX, y: e.clientY, viewX: view.viewX, viewY: view.viewY };
            isPanningRef.current = true;
            setIsPanning(true);
          }
        }}
      >
        <Stage
          width={containerSize.width || canvasWidth}
          height={containerSize.height || canvasHeight}
          scaleX={viewScale}
          scaleY={viewScale}
          x={viewX}
          y={viewY}
          style={{
            maxWidth: "100%",
            maxHeight: "100%",
            cursor: isPanning || spacePressedRef.current ? "grabbing" : tool === "select" ? "default" : "crosshair",
          }}
          onClick={handleClick}
          onDblClick={() => {
            if (tool === "polygon" || tool === "pen") finishDrawing();
          }}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onWheel={handleWheel}
          onContextMenu={e => e.evt.preventDefault()}
        >
          <Layer>
            {showFloorPlan && image && (
              <KonvaImage
                image={image}
                x={0}
                y={0}
                width={canvasWidth}
                height={canvasHeight}
                opacity={0.55}
              />
            )}
            {gridEnabled &&
              Array.from({ length: Math.floor(canvasWidth / 100) + 1 }, (_, i) => (
                <Line key={`gv-${i}`} points={[i * 100, 0, i * 100, canvasHeight]} stroke="#e8e8e8" strokeWidth={1} />
              ))}
            {gridEnabled &&
              Array.from({ length: Math.floor(canvasHeight / 100) + 1 }, (_, i) => (
                <Line key={`gh-${i}`} points={[0, i * 100, canvasWidth, i * 100]} stroke="#e8e8e8" strokeWidth={1} />
              ))}
            {guideEnabled && (
              <>
                <Line points={[canvasWidth / 2, 0, canvasWidth / 2, canvasHeight]} stroke="#f5222d" dash={[8, 6]} strokeWidth={1} opacity={0.45} listening={false} />
                <Line points={[0, canvasHeight / 2, canvasWidth, canvasHeight / 2]} stroke="#f5222d" dash={[8, 6]} strokeWidth={1} opacity={0.45} listening={false} />
              </>
            )}
            {marqueeStart && marqueeEnd && (() => {
              const rect = rectFromPoints(marqueeStart, marqueeEnd, (3 / canvasWidth) * 100);
              if (!rect) return null;
              return (
                <Rect
                  x={toCanvasX(rect.x, canvasWidth)}
                  y={toCanvasY(rect.y, canvasHeight)}
                  width={(rect.width / 100) * canvasWidth}
                  height={(rect.height / 100) * canvasHeight}
                  fill="rgba(22,119,255,0.12)"
                  stroke="#1677ff"
                  dash={[6, 4]}
                  strokeWidth={1.5}
                  listening={false}
                />
              );
            })()}
            {pendingRegions.map(r => {
              const selected = selectedRegionIds.includes(`pending:${r.id}`);
              return (
                <Line
                  id={`pending:${r.id}`}
                  key={r.id}
                  points={pointsToKonva(r.points, canvasWidth, canvasHeight)}
                  closed
                  stroke={selected ? "#1677ff" : "#fa8c16"}
                  dash={selected ? undefined : [6, 4]}
                  strokeWidth={selected ? 3 : 2}
                  draggable={tool === "select"}
                  ref={node => {
                    if (node) {
                      regionNodeRefs.current.set(`pending:${r.id}`, node);
                    } else {
                      regionNodeRefs.current.delete(`pending:${r.id}`);
                    }
                  }}
                  onMouseDown={e => {
                    e.cancelBubble = true;
                  }}
                  onClick={e => {
                    e.cancelBubble = true;
                    setState({ selectedRegionIds: [`pending:${r.id}`], selectedRiskPointId: null, selectedTextId: null });
                  }}
                  onDragStart={() => {
                    pendingDragOriginRef.current.set(r.id, r.points);
                  }}
                  onDragEnd={e => {
                    const origin = pendingDragOriginRef.current.get(r.id) ?? r.points;
                    const dx = (e.target.x() / canvasWidth) * 100;
                    const dy = (e.target.y() / canvasHeight) * 100;
                    const moved = origin.map(pt => clampPoint({ x: pt.x + dx, y: pt.y + dy }));
                    pendingDragOriginRef.current.delete(r.id);
                    e.target.position({ x: 0, y: 0 });
                    commit();
                    setSnapshot({
                      pendingRegions: useRiskMappingWorkbenchStore.getState().pendingRegions.map(item =>
                        item.id === r.id ? { ...item, points: moved } : item,
                      ),
                    });
                  }}
                  onTransformStart={() => handleRegionTransformStart(`pending:${r.id}`, r.points)}
                  onTransformEnd={handleRegionTransformEnd}
                />
              );
            })}
            {draftStart && draftEnd && tool === "rect" && (
              <Rect
                x={Math.min(toCanvasX(draftStart.x, canvasWidth), toCanvasX(draftEnd.x, canvasWidth))}
                y={Math.min(toCanvasY(draftStart.y, canvasHeight), toCanvasY(draftEnd.y, canvasHeight))}
                width={Math.abs(toCanvasX(draftEnd.x, canvasWidth) - toCanvasX(draftStart.x, canvasWidth))}
                height={Math.abs(toCanvasY(draftEnd.y, canvasHeight) - toCanvasY(draftStart.y, canvasHeight))}
                dash={[4, 4]}
                stroke="#1677ff"
                fill="rgba(22, 119, 255, 0.08)"
              />
            )}
            {draftStart && draftEnd && tool === "circle" && (
              <KonvaCircle
                x={toCanvasX(draftStart.x, canvasWidth)}
                y={toCanvasY(draftStart.y, canvasHeight)}
                radius={Math.hypot(
                  toCanvasX(draftEnd.x, canvasWidth) - toCanvasX(draftStart.x, canvasWidth),
                  toCanvasY(draftEnd.y, canvasHeight) - toCanvasY(draftStart.y, canvasHeight),
                )}
                dash={[4, 4]}
                stroke="#1677ff"
                fill="rgba(22, 119, 255, 0.08)"
              />
            )}
            {draftPoints.length > 0 && (
              <Line
                points={pointsToKonva(draftCursor ? [...draftPoints, draftCursor] : draftPoints, canvasWidth, canvasHeight)}
                closed={tool === "polygon" && !draftCursor}
                stroke="#1677ff"
                dash={[4, 4]}
                strokeWidth={2}
              />
            )}
            {draftPoints.map((p, index) => (
              <KonvaCircle
                key={`${p.x}-${p.y}-${index}`}
                x={toCanvasX(p.x, canvasWidth)}
                y={toCanvasY(p.y, canvasHeight)}
                radius={4}
                fill="#1677ff"
                stroke="#fff"
                strokeWidth={1}
              />
            ))}
            {tool === "pen" && (
              <>
                {penPathPoints && (
                  <Line
                    points={pointsToKonva(penPathPoints, canvasWidth, canvasHeight)}
                    stroke="#1677ff"
                    strokeWidth={2}
                    listening={false}
                  />
                )}
                {penPreviewPoints && (
                  <Line
                    points={pointsToKonva(penPreviewPoints, canvasWidth, canvasHeight)}
                    stroke="#1677ff"
                    dash={[4, 4]}
                    strokeWidth={2}
                    listening={false}
                  />
                )}
                {penCursorPreview && (
                  <Line
                    points={pointsToKonva(penCursorPreview, canvasWidth, canvasHeight)}
                    stroke="#8b5cf6"
                    dash={[4, 4]}
                    strokeWidth={1.5}
                    listening={false}
                  />
                )}
                {penAnchors.map((anchor, index) => (
                  <Fragment key={`anchor-${index}`}>
                    {anchor.handle && (
                      <Line
                        points={pointsToKonva([anchor.point, anchor.handle], canvasWidth, canvasHeight)}
                        stroke="#8b5cf6"
                        dash={[4, 4]}
                        strokeWidth={1.5}
                        listening={false}
                      />
                    )}
                    <KonvaCircle
                      x={toCanvasX(anchor.point.x, canvasWidth)}
                      y={toCanvasY(anchor.point.y, canvasHeight)}
                      radius={4}
                      fill="#1677ff"
                      stroke="#fff"
                      strokeWidth={2}
                      listening={false}
                    />
                    {anchor.handle && (
                      <KonvaCircle
                        x={toCanvasX(anchor.handle.x, canvasWidth)}
                        y={toCanvasY(anchor.handle.y, canvasHeight)}
                        radius={3}
                        fill="#8b5cf6"
                        stroke="#fff"
                        strokeWidth={1.5}
                        listening={false}
                      />
                    )}
                  </Fragment>
                ))}
                {penActive && (
                  <>
                    {penActive.handle && (
                      <Line
                        points={pointsToKonva([penActive.point, penActive.handle], canvasWidth, canvasHeight)}
                        stroke="#8b5cf6"
                        dash={[4, 4]}
                        strokeWidth={1.5}
                        listening={false}
                      />
                    )}
                    <KonvaCircle
                      x={toCanvasX(penActive.point.x, canvasWidth)}
                      y={toCanvasY(penActive.point.y, canvasHeight)}
                      radius={4}
                      fill="#1677ff"
                      stroke="#fff"
                      strokeWidth={2}
                      listening={false}
                    />
                    {penActive.handle && (
                      <KonvaCircle
                        x={toCanvasX(penActive.handle.x, canvasWidth)}
                        y={toCanvasY(penActive.handle.y, canvasHeight)}
                        radius={3}
                        fill="#8b5cf6"
                        stroke="#fff"
                        strokeWidth={1.5}
                        listening={false}
                      />
                    )}
                  </>
                )}
              </>
            )}
            {zones.map(z =>
              (z.floor_plan_polygon?.polygons || []).map(p => {
                const regionId = `zone:${z.id}:${p.id}`;
                const selected = selectedRegionIds.includes(regionId);
                const centroid = polygonCentroid(p.points);
                const labelWidth = z.name.length * 14 + 12;
                const labelX = toCanvasX(centroid.x, canvasWidth) - labelWidth / 2;
                const labelY = toCanvasY(centroid.y, canvasHeight) - 12;
                return (
                  <Fragment
                    key={regionId}
                  >
                    <Line
                      id={regionId}
                      points={pointsToKonva(p.points, canvasWidth, canvasHeight)}
                      closed
                      fill={zoneColor(z) || "#d9d9d9"}
                      opacity={0.22}
                      stroke={selected ? "#1677ff" : "#ffffff"}
                      strokeWidth={selected ? 3.5 : 2.5}
                      draggable={tool === "select"}
                      ref={node => {
                        if (node) {
                          regionNodeRefs.current.set(regionId, node);
                        } else {
                          regionNodeRefs.current.delete(regionId);
                        }
                      }}
                      onMouseDown={e => {
                        e.cancelBubble = true;
                      }}
                      onClick={e => {
                        e.cancelBubble = true;
                        setState({
                          selectedRegionIds: [regionId],
                          selectedRiskPointId: null,
                          selectedTextId: null,
                          selectedZoneId: z.id,
                        });
                      }}
                      onDragStart={e => {
                        const store = useRiskMappingWorkbenchStore.getState();
                        if (!store.selectedRegionIds.includes(regionId)) {
                          store.setSelectedRegions([regionId]);
                        }
                        const origin = new Map<string, RiskPolygonPoint[]>();
                        useRiskMappingWorkbenchStore.getState().selectedRegionIds.forEach(id => {
                          const pts = resolveRegionPoints(id);
                          if (pts) origin.set(id, pts);
                        });
                        if (!origin.size) origin.set(regionId, p.points);
                        groupDragRef.current = { startX: e.target.x(), startY: e.target.y(), origin };
                        dragWritebackRef.current = false;
                      }}
                      onDragMove={e => {
                        const group = groupDragRef.current;
                        if (!group || group.origin.size < 2) return;
                        const dx = e.target.x() - group.startX;
                        const dy = e.target.y() - group.startY;
                        group.origin.forEach((_pts, id) => {
                          if (id === regionId) return;
                          regionNodeRefs.current.get(id)?.position({ x: dx, y: dy });
                        });
                      }}
                      onDragEnd={e => {
                        const dxPx = e.target.x();
                        const dyPx = e.target.y();
                        e.target.position({ x: 0, y: 0 });
                        // Konva 会为每个选中节点各触发一次 dragEnd：只允许有位移的那次写回，
                        // 否则后续 0 位移的 dragEnd 会把整体位移覆盖掉。
                        if (dragWritebackRef.current) return;
                        if (Math.abs(dxPx) < 0.01 && Math.abs(dyPx) < 0.01) return;
                        dragWritebackRef.current = true;
                        const dx = (dxPx / canvasWidth) * 100;
                        const dy = (dyPx / canvasHeight) * 100;
                        const group = groupDragRef.current;
                        groupDragRef.current = null;
                        const targets =
                          group?.origin ?? new Map<string, RiskPolygonPoint[]>([[regionId, resolveRegionPoints(regionId) ?? p.points]]);
                        const updates = new Map<string, RiskPolygonPoint[]>();
                        targets.forEach((points, id) => {
                          updates.set(id, points.map(pt => clampPoint({ x: pt.x + dx, y: pt.y + dy })));
                          regionNodeRefs.current.get(id)?.position({ x: 0, y: 0 });
                        });
                        const store = useRiskMappingWorkbenchStore.getState();
                        const applied = applyRegionPointUpdates(store.zones, store.pendingRegions, updates);
                        commit();
                        setSnapshot(applied);
                      }}
                      onTransformStart={() => handleRegionTransformStart(regionId, p.points)}
                      onTransformEnd={handleRegionTransformEnd}
                    />
                    <Rect
                      x={labelX}
                      y={labelY}
                      width={labelWidth}
                      height={24}
                      fill="rgba(17,24,39,0.72)"
                      cornerRadius={4}
                      listening={false}
                    />
                    <KonvaText
                      x={labelX}
                      y={labelY}
                      text={z.name}
                      fontSize={14}
                      fontStyle="bold"
                      fill="#ffffff"
                      align="center"
                      width={labelWidth}
                      height={24}
                      verticalAlign="middle"
                      listening={false}
                    />
                  </Fragment>
                );
              }),
            )}
            {texts.map(t => {
              const selected = selectedTextId === t.id;
              return (
                <KonvaText
                  key={t.id}
                  x={toCanvasX(t.x, canvasWidth)}
                  y={toCanvasY(t.y, canvasHeight)}
                  text={t.content}
                  fontSize={t.font_size}
                  fill={t.color}
                  rotation={t.rotation}
                  stroke={selected ? "#1677ff" : undefined}
                  strokeWidth={selected ? 1 : 0}
                  draggable={tool === "select"}
                  onClick={e => {
                    e.cancelBubble = true;
                    setState({ selectedTextId: t.id, selectedRiskPointId: null, selectedRegionIds: [] });
                  }}
                  onDragEnd={e => {
                    commit();
                    setSnapshot({
                      texts: useRiskMappingWorkbenchStore.getState().texts.map(item =>
                        item.id === t.id
                          ? {
                              ...item,
                              x: Math.round(Math.min(100, Math.max(0, (e.target.x() / canvasWidth) * 100)) * 100) / 100,
                              y: Math.round(Math.min(100, Math.max(0, (e.target.y() / canvasHeight) * 100)) * 100) / 100,
                            }
                          : item,
                      ),
                    });
                  }}
                  onDblClick={e => {
                    e.cancelBubble = true;
                    setState({ selectedTextId: t.id, selectedRiskPointId: null, selectedRegionIds: [] });
                    setEditingTextId(t.id);
                    setEditContent(t.content);
                    setEditFontSize(t.font_size);
                    setEditColor(t.color);
                  }}
                />
              );
            })}
            <WorkbenchRiskPointLayer />
            {tool === "select" && (() => {
              const nodes = selectedRegionIds
                .map(id => regionNodeRefs.current.get(id))
                .filter((node): node is KonvaNode => node !== undefined);
              if (!nodes.length) return null;
              return (
                <Transformer
                  ref={transformerRef}
                  nodes={nodes}
                  rotateEnabled
                  flipEnabled={false}
                  anchorSize={10}
                  borderStroke="#1677ff"
                  anchorStroke="#1677ff"
                  anchorFill="#ffffff"
                />
              );
            })()}
          </Layer>
        </Stage>
      </div>
      <Modal
        title="编辑文字标注"
        open={!!editingText}
        onCancel={() => setEditingTextId(null)}
        onOk={() => {
          if (!editingText) return;
          commit();
          setSnapshot({
            texts: useRiskMappingWorkbenchStore.getState().texts.map(t =>
              t.id === editingText.id
                ? { ...t, content: editContent.trim() || t.content, font_size: editFontSize, color: editColor }
                : t,
            ),
          });
          setEditingTextId(null);
        }}
        okText="保存"
        cancelText="取消"
      >
        {editingText && (
          <Space direction="vertical" style={{ width: "100%" }}>
            <div>
              <div style={{ marginBottom: 4, fontSize: 12, color: "#666" }}>内容</div>
              <Input value={editContent} onChange={e => setEditContent(e.target.value)} />
            </div>
            <div>
              <div style={{ marginBottom: 4, fontSize: 12, color: "#666" }}>字号</div>
              <InputNumber min={8} max={72} value={editFontSize} onChange={v => setEditFontSize(v ?? 14)} style={{ width: "100%" }} />
            </div>
            <div>
              <div style={{ marginBottom: 4, fontSize: 12, color: "#666" }}>颜色</div>
              <Input type="color" value={editColor} onChange={e => setEditColor(e.target.value)} style={{ width: "100%", height: 32 }} />
            </div>
            <Button
              danger
              block
              icon={<DeleteOutlined />}
              onClick={() => {
                commit();
                useRiskMappingWorkbenchStore.getState().deleteText(editingText.id);
                setEditingTextId(null);
              }}
            >
              删除标注
            </Button>
          </Space>
        )}
      </Modal>
    </>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { sanitizeHtml } from "@/utils/sanitize";
import {
  Alert,
  Badge,
  Button,
  Card,
  Empty,
  message,
  Modal,
  Progress,
  Space,
  Spin,
  Tag,
  Typography,
} from "antd";
import {
  AuditOutlined,
  CheckCircleFilled,
  CloseCircleFilled,
  ExportOutlined,
  EyeOutlined,
  FileSyncOutlined,
  LoadingOutlined,
  SaveOutlined,
  SettingOutlined,
  StopOutlined,
  ThunderboltOutlined,
} from "@ant-design/icons";
import type {
  ReportAdapter,
  ReportChapter,
  ReportDocument,
  ReportIssue,
  ReportStreamEvent,
} from "@/types/reportWorkspace";
import type { ChapterDef } from "@/services/riskAssessmentService";
import { createRiskAssessmentVersion } from "@/services/riskAssessmentService";
import { createResourceInvestigationVersion } from "@/services/resourceInvestigationService";
import TiptapEditor from "@/components/report/TiptapEditor";
import ReportChapterActions from "@/components/report/ReportChapterActions";
import ReviewDrawer from "@/components/report/ReviewDrawer";
import { StylePanel } from "@/components/plan/StylePanel";
import { DEFAULT_STYLE } from "@/components/plan/stylePreference";
import DiffPreviewModal from "@/components/plan/DiffPreviewModal";
import AiNotConfiguredHint from "@/components/common/AiNotConfiguredHint";
import { addFailedChapter } from "@/components/report/failedChapters";
import { aiErrorDisplay } from "@/utils/aiUnavailable";
import { htmlToMarkdown, renderReportMarkdown } from "@/utils/reportMarkdown";

const { Text, Title } = Typography;

const RISK_FALLBACK_CHAPTERS: ChapterDef[] = [
  { key: "ch1_hazard_id", title: "一、危险有害因素辨识分析" },
  { key: "ch2_summary", title: "二、危险有害因素辨识汇总" },
  { key: "ch3_risk_eval", title: "三、风险等级评估" },
  { key: "ch4_measures", title: "四、现有管控措施评价" },
  { key: "ch5_conclusion", title: "五、风险评估结论与建议" },
];

const RESOURCE_FALLBACK_CHAPTERS: ChapterDef[] = [
  { key: "ch1_purpose", title: "一、调查目的与依据" },
  { key: "ch2_basic_info", title: "二、企业基本情况与风险概况" },
  { key: "ch3_internal", title: "三、内部应急资源调查" },
  { key: "ch4_external", title: "四、外部救援资源调查" },
  { key: "ch5_gap_analysis", title: "五、应急资源需求与能力评估" },
  { key: "ch6_conclusion", title: "六、调查结论与建议" },
];

interface ReportWorkspaceProps {
  adapter: ReportAdapter;
  enterpriseId: string;
  meta: { emptyTitle: string; emptyDesc: string; generateLabel: string };
  /** 报告类型：risk=风险评估，resource=应急资源调查；决定版本/预览路由与章节定义 */
  kind?: "risk" | "resource";
  /** 章节定义；缺省时按 kind 使用内置定义（与后端 CHAPTER_DEFINITIONS 对齐） */
  chapters?: ChapterDef[];
}

type SaveState = "idle" | "saving" | "saved" | "error";
type GenerationMode = "full" | "chapter" | null;

interface DiffItem {
  sectionKey: string;
  original: string;
  revised: string;
}

const SAVE_DEBOUNCE_MS = 1500;

export default function ReportWorkspace({
  adapter,
  enterpriseId,
  meta,
  kind = "risk",
  chapters: chapterDefsProp,
}: ReportWorkspaceProps) {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [doc, setDoc] = useState<ReportDocument | null>(null);
  const [selectedKey, setSelectedKey] = useState<string | null>(null);
  const [contentByKey, setContentByKey] = useState<Record<string, string>>({});
  const [saveState, setSaveState] = useState<Record<string, SaveState>>({});
  const [generating, setGenerating] = useState<GenerationMode>(null);
  const [generatingKeys, setGeneratingKeys] = useState<Set<string>>(new Set());
  const [failedChapters, setFailedChapters] = useState<ReportChapter[]>([]);
  const [batchProgress, setBatchProgress] = useState({ current: 0, total: 0, message: "" });
  const [thinkingText, setThinkingText] = useState("");
  const [aiUnavailable, setAiUnavailable] = useState(false);

  const [styleOpen, setStyleOpen] = useState(false);
  const [styleValue, setStyleValue] = useState<typeof DEFAULT_STYLE>(DEFAULT_STYLE);
  const [savingStyle, setSavingStyle] = useState(false);

  const [reviewOpen, setReviewOpen] = useState(false);
  const [reviewIssues, setReviewIssues] = useState<ReportIssue[]>([]);
  const [reviewing, setReviewing] = useState(false);
  const [applyingReview, setApplyingReview] = useState(false);
  const [diffQueue, setDiffQueue] = useState<DiffItem[]>([]);
  const [diffIndex, setDiffIndex] = useState(-1);

  const [genModalKey, setGenModalKey] = useState<string | null>(null);
  const [savingVersion, setSavingVersion] = useState(false);
  const [merging, setMerging] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [collapsed, setCollapsed] = useState(false);

  const allControllersRef = useRef<AbortController[]>([]);
  const genBufferRef = useRef<Record<string, string>>({});
  const pendingSavesRef = useRef<Record<string, string>>({});
  const saveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const saveChainRef = useRef<Promise<void>>(Promise.resolve());
  const dirtyRef = useRef<Set<string>>(new Set());

  const fallbackChapters = useMemo(
    () => (kind === "resource" ? RESOURCE_FALLBACK_CHAPTERS : RISK_FALLBACK_CHAPTERS),
    [kind],
  );

  const chapterDefs = useMemo(() => {
    const base = chapterDefsProp && chapterDefsProp.length > 0 ? chapterDefsProp : fallbackChapters;
    // 若已加载草稿章节（key/title），优先用草稿顺序展示，补上缺失定义
    const loaded = doc?.chapters || [];
    const known = new Set<string>();
    const merged: ChapterDef[] = [];
    loaded.forEach((ch) => {
      known.add(ch.key);
      merged.push({ key: ch.key, title: ch.title });
    });
    base.forEach((c) => {
      if (!known.has(c.key)) merged.push({ key: c.key, title: c.title });
    });
    return merged;
  }, [chapterDefsProp, fallbackChapters, doc]);

  const selectedDef = chapterDefs.find((c) => c.key === selectedKey) || null;
  const editorHtml = selectedKey ? renderReportMarkdown(contentByKey[selectedKey] || "") : "";
  const chapterTitleMap = useMemo(() => {
    const map: Record<string, string> = {};
    chapterDefs.forEach((c) => { map[c.key] = c.title; });
    return map;
  }, [chapterDefs]);

  /** 更新某个章节的内容（markdown 规范），供 SSE / 编辑 / diff 应用共用 */
  const setChapterContent = useCallback((key: string, md: string) => {
    setContentByKey((prev) => ({ ...prev, [key]: md }));
  }, []);

  const saveOne = useCallback(
    async (key: string, md: string) => {
      setSaveState((prev) => ({ ...prev, [key]: "saving" }));
      try {
        await adapter.saveChapter(enterpriseId, key, md);
        setSaveState((prev) => ({ ...prev, [key]: "saved" }));
        dirtyRef.current.delete(key);
      } catch (err) {
        setSaveState((prev) => ({ ...prev, [key]: "error" }));
        const disp = aiErrorDisplay(
          err instanceof Error ? err.message : undefined,
          "章节保存失败，点击重试",
        );
        if (disp.notConfigured) setAiUnavailable(true);
        else message.error(disp.text);
      }
    },
    [adapter, enterpriseId],
  );

  const flushPendingSaves = useCallback(() => {
    if (saveTimerRef.current) {
      clearTimeout(saveTimerRef.current);
      saveTimerRef.current = null;
    }
    const keys = Object.keys(pendingSavesRef.current);
    if (keys.length === 0) return;
    const snapshots = { ...pendingSavesRef.current };
    pendingSavesRef.current = {};
    keys.forEach((key) => {
      if (dirtyRef.current.has(key) || snapshots[key] !== undefined) {
        const content = snapshots[key];
        if (content !== undefined) {
          saveChainRef.current = saveChainRef.current
            .then(() => saveOne(key, content))
            .catch(() => {});
        }
      }
    });
  }, [saveOne]);

  /** 编辑内容进入防抖保存队列（1.5s） */
  const scheduleSave = useCallback(
    (key: string, md: string) => {
      pendingSavesRef.current[key] = md;
      dirtyRef.current.add(key);
      setSaveState((prev) => ({ ...prev, [key]: "idle" }));
      if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
      saveTimerRef.current = setTimeout(() => {
        saveTimerRef.current = null;
        flushPendingSaves();
      }, SAVE_DEBOUNCE_MS);
    },
    [flushPendingSaves],
  );

  const loadDocument = useCallback(async () => {
    try {
      const next = await adapter.load(enterpriseId);
      setDoc(next);
      setContentByKey((prev) => {
        const merged = { ...prev };
        (next.chapters || []).forEach((ch) => {
          // 保留用户在编辑器中的未保存改动；其余以服务端为准
          if (!dirtyRef.current.has(ch.key)) merged[ch.key] = ch.content || "";
        });
        return merged;
      });
      setSaveState({});
      setSelectedKey((prev) => prev ?? next.chapters?.[0]?.key ?? null);
    } catch {
      // 无报告行 → 空态（在生成前 report 不存在，load 404 属预期，不打断首次生成引导）
      setDoc(null);
    } finally {
      setLoading(false);
    }
  }, [adapter, enterpriseId]);

  // 切换企业/适配器时进入加载态（渲染期调整 state，避免 effect 内同步 setState）
  const [prevLoadKey, setPrevLoadKey] = useState<string>("");
  const loadKey = String(enterpriseId ?? "");
  if (loadKey !== prevLoadKey) {
    setPrevLoadKey(loadKey);
    setLoading(true);
  }

  useEffect(() => {
    void loadDocument();
  }, [loadDocument]);

  // 后台生成中：每 4 秒拉一次报告，展示已保存章节
  useEffect(() => {
    if (!doc || doc.status !== "generating") return;
    const timer = setInterval(() => void loadDocument(), 4000);
    return () => clearInterval(timer);
  }, [doc, loadDocument]);

  // 卸载/离开前提示未保存内容
  useEffect(() => {
    const onBeforeUnload = (e: BeforeUnloadEvent) => {
      if (dirtyRef.current.size > 0) {
        e.preventDefault();
        e.returnValue = "";
      }
    };
    window.addEventListener("beforeunload", onBeforeUnload);
    return () => {
      window.removeEventListener("beforeunload", onBeforeUnload);
      // 离开页面即停止进行中的生成：后端会把已完成章节落为草稿，
      // 避免“生成到一半退出”后整份作废或残留 generating 空行
      allControllersRef.current.forEach((c) => c.abort());
      allControllersRef.current = [];
      flushPendingSaves();
    };
  }, [flushPendingSaves]);

  // 章节切换前立即落盘待保存内容
  const selectChapter = useCallback(
    (key: string) => {
      flushPendingSaves();
      setSelectedKey(key);
    },
    [flushPendingSaves],
  );

  const showGenError = useCallback(
    (raw: string | null | undefined, fallback: string) => {
      const disp = aiErrorDisplay(raw, fallback);
      if (disp.notConfigured) setAiUnavailable(true);
      else message.error(disp.text);
    },
    [],
  );

  const stopGeneration = useCallback(() => {
    allControllersRef.current.forEach((c) => c.abort());
    allControllersRef.current = [];
    setGenerating(null);
    setGeneratingKeys(new Set());
    setBatchProgress({ current: 0, total: 0, message: "" });
  }, []);

  /** 全量生成：adapter.generateAll（SSE） */
  const startFullGenerate = useCallback(async () => {
    if (doc?.status === "completed") {
      const confirmed = await new Promise<boolean>((resolve) => {
        Modal.confirm({
          title: "重新生成将覆盖当前报告，确定继续？",
          okText: "重新生成",
          okButtonProps: { danger: true },
          cancelText: "取消",
          onOk: () => resolve(true),
          onCancel: () => resolve(false),
        });
      });
      if (!confirmed) return;
    }
    if (generating) return;
    flushPendingSaves();
    allControllersRef.current.forEach((c) => c.abort());
    allControllersRef.current = [];
    genBufferRef.current = {};
    setGenerating("full");
    setGeneratingKeys(new Set());
    setFailedChapters([]);
    setBatchProgress({ current: 0, total: 0, message: "准备开始..." });
    setAiUnavailable(false);

    const controller = adapter.generateAll(
      enterpriseId,
      {
        onEvent: (event: ReportStreamEvent) => {
          switch (event.type) {
            case "thinking": {
              setThinkingText(event.message || "");
              break;
            }
            case "progress": {
              setThinkingText("");
              const sk = event.section_key as string | undefined;
              if (sk) setGeneratingKeys((prev) => new Set(prev).add(sk));
              setBatchProgress((prev) => ({
                current: event.current ?? prev.current,
                total: event.total ?? prev.total,
                message: event.message || prev.message,
              }));
              break;
            }
            case "chunk": {
              setThinkingText("");
              const sk = event.section_key as string | undefined;
              if (sk && event.content) {
                genBufferRef.current[sk] = (genBufferRef.current[sk] || "") + String(event.content);
                setChapterContent(sk, genBufferRef.current[sk]);
              }
              break;
            }
            case "section_done": {
              setThinkingText("");
              const sk = event.section_key as string | undefined;
              if (sk) {
                setGeneratingKeys((prev) => {
                  const n = new Set(prev);
                  n.delete(sk);
                  return n;
                });
                setSaveState((prev) => ({ ...prev, [sk]: "saved" }));
              }
              break;
            }
            case "batch_done": {
              setThinkingText("");
              const rawChapters = (event.chapters as unknown) || event.content || "";
              if (typeof rawChapters === "string" && rawChapters.trim()) {
                try {
                  const parsed = JSON.parse(rawChapters);
                  if (Array.isArray(parsed)) {
                    const merged: Record<string, string> = {};
                    parsed.forEach((c) => {
                      if (c && c.key) merged[c.key] = c.content || "";
                    });
                    genBufferRef.current = { ...genBufferRef.current, ...merged };
                  }
                } catch {
                  // 后端 chapters 可能不是 JSON 字符串；忽略，内容已按 chunk 累积
                }
              }
              setGenerating(null);
              setGeneratingKeys(new Set());
              setBatchProgress({ current: 0, total: 0, message: "" });
              const failed = event.failed_sections as Array<{ key: string; title?: string }> | undefined;
              if (failed && failed.length > 0) {
                setFailedChapters(
                  failed.map((f) => ({ key: f.key, title: f.title || f.key, content: "" })),
                );
                message.warning(`${failed.length} 个章节生成失败，可单独重试`);
              } else {
                message.success("报告草稿生成完成");
              }
              void loadDocument();
              break;
            }
            case "error": {
              setThinkingText("");
              const sk = event.section_key as string | undefined;
              if (sk) {
                setFailedChapters((prev) => addFailedChapter(prev, sk, sk));
              }
              showGenError(event.message, "生成失败，请重试");
              setGenerating(null);
              setGeneratingKeys(new Set());
              break;
            }
          }
        },
        onError: (error) => {
          setThinkingText("");
          showGenError(error, "生成失败，请重试");
          setGenerating(null);
          setGeneratingKeys(new Set());
        },
        onComplete: () => {},
      },
    );
    allControllersRef.current.push(controller);
  }, [
    adapter, enterpriseId, doc, generating, flushPendingSaves,
    setChapterContent, showGenError, loadDocument,
  ]);

  /** 单章生成/重生成：adapter.generateChapter / regenerateChapter（SSE） */
  const runChapterGeneration = useCallback(
    (key: string, mode: "generate" | "regenerate") => {
      const def = fallbackChapters.find((c) => c.key === key) || chapterDefs.find((c) => c.key === key);
      const title = def?.title || key;
      const previous = contentByKey[key] || "";
      flushPendingSaves();
      allControllersRef.current.forEach((c) => c.abort());
      allControllersRef.current = [];
      genBufferRef.current = {};
      setGenerating("chapter");
      setGeneratingKeys(new Set([key]));
      setAiUnavailable(false);

      const cb = {
        onEvent: (event: ReportStreamEvent) => {
          switch (event.type) {
            case "thinking": {
              setThinkingText(event.message || "");
              break;
            }
            case "chunk": {
              setThinkingText("");
              if (event.content) {
                genBufferRef.current[key] = (genBufferRef.current[key] || "") + String(event.content);
                setChapterContent(key, genBufferRef.current[key]);
              }
              break;
            }
            case "section_done": {
              setThinkingText("");
              setGenerating(null);
              setGeneratingKeys(new Set());
              const finalMd = genBufferRef.current[key] || "";
              setChapterContent(key, finalMd);
              setSaveState((prev) => ({ ...prev, [key]: "saved" }));
              if (mode === "regenerate" && previous && finalMd && previous !== finalMd) {
                setDiffQueue([{ sectionKey: key, original: previous, revised: finalMd }]);
                setDiffIndex(0);
              } else if (previous && finalMd) {
                message.success(`「${title}」已重新生成`);
              }
              break;
            }
            case "error": {
              setThinkingText("");
              setGenerating(null);
              setGeneratingKeys(new Set());
              showGenError(event.message, "单章生成失败");
              break;
            }
          }
        },
        onError: (error: string) => {
          setThinkingText("");
          setGenerating(null);
          setGeneratingKeys(new Set());
          showGenError(error, "单章生成失败");
        },
        onComplete: () => {},
      };
      const controller =
        mode === "regenerate"
          ? adapter.regenerateChapter(enterpriseId, key, cb)
          : adapter.generateChapter(enterpriseId, key, cb);
      allControllersRef.current.push(controller);
    },
    [
      adapter, enterpriseId, contentByKey, fallbackChapters, chapterDefs,
      flushPendingSaves, setChapterContent, showGenError,
    ],
  );

  /** 保存版本：按 kind 调对应 service 的 createVersion */
  const handleSaveVersion = useCallback(async () => {
    if (savingVersion) return;
    setSavingVersion(true);
    try {
      if (kind === "resource") {
        await createResourceInvestigationVersion(enterpriseId);
      } else {
        await createRiskAssessmentVersion(enterpriseId);
      }
      message.success("版本已保存");
    } catch (err) {
      showGenError(err instanceof Error ? err.message : undefined, "保存版本失败");
    } finally {
      setSavingVersion(false);
    }
  }, [kind, enterpriseId, savingVersion, showGenError]);

  /** 合并定稿：adapter.merge */
  const handleMerge = useCallback(async () => {
    if (merging) return;
    const chapters: ReportChapter[] = chapterDefs
      .map((c) => ({
        key: c.key,
        title: c.title,
        content: contentByKey[c.key] || "",
      }))
      .filter((c) => c.content && c.content.trim());
    if (chapters.length === 0) {
      message.warning("请先生成章节内容再合并");
      return;
    }
    setMerging(true);
    try {
      await adapter.merge(enterpriseId, chapters);
      message.success("报告合并完成");
      await loadDocument();
    } catch (err) {
      showGenError(err instanceof Error ? err.message : undefined, "合并失败，请重试");
    } finally {
      setMerging(false);
    }
  }, [merging, chapterDefs, contentByKey, adapter, enterpriseId, loadDocument, showGenError]);

  /** AI 审查（确定性规则） */
  const handleReview = useCallback(async () => {
    if (reviewing) return;
    setReviewing(true);
    try {
      const issues = await adapter.review(enterpriseId, null);
      setReviewIssues(issues);
      setReviewOpen(true);
      if (issues.length === 0) {
        // Drawer 内 Empty 提示，不额外打扰
      }
    } catch (err) {
      showGenError(err instanceof Error ? err.message : undefined, "审查失败，请重试");
    } finally {
      setReviewing(false);
    }
  }, [adapter, enterpriseId, reviewing, showGenError]);

  const applyReview = useCallback(
    async (sectionKeys: string[]) => {
      if (applyingReview || sectionKeys.length === 0) return;
      setApplyingReview(true);
      try {
        const applied = await adapter.applyReview(enterpriseId, sectionKeys);
        const diffs: DiffItem[] = applied.map((r) => ({
          sectionKey: r.section_key,
          original: r.original || "",
          revised: r.revised || "",
        }));
        if (diffs.length === 0) {
          message.info("所选章节没有需要修订的内容");
          return;
        }
        setDiffQueue(diffs);
        setDiffIndex(0);
      } catch (err) {
        showGenError(err instanceof Error ? err.message : undefined, "生成修订失败");
      } finally {
        setApplyingReview(false);
      }
    },
    [adapter, enterpriseId, applyingReview, showGenError],
  );

  /** Diff 逐条确认：接受 → 更新内存章节并保存；拒绝 → 保持原文 */
  const closeDiff = useCallback(
    (accepted: boolean) => {
      const item = diffQueue[diffIndex];
      if (item) {
        if (accepted) {
          setChapterContent(item.sectionKey, item.revised);
          // 立即保存修订结果（修订内容较大，不再等防抖窗口）
          setSaveState((prev) => ({ ...prev, [item.sectionKey]: "saving" }));
          void saveOne(item.sectionKey, item.revised);
        }
      }
      if (diffIndex + 1 < diffQueue.length) {
        setDiffIndex((i) => i + 1);
      } else {
        setDiffQueue([]);
        setDiffIndex(-1);
        setReviewOpen(false);
        setReviewIssues([]);
      }
    },
    [diffQueue, diffIndex, saveOne, setChapterContent],
  );

  const openStyleModal = useCallback(async () => {
    setStyleOpen(true);
    try {
      const saved = await adapter.getStyle(enterpriseId);
      setStyleValue({ ...DEFAULT_STYLE, ...saved } as typeof DEFAULT_STYLE);
    } catch {
      // 默认风格兜底
    }
  }, [adapter, enterpriseId]);

  const saveStyle = useCallback(async () => {
    setSavingStyle(true);
    try {
      const stylePayload: Record<string, string> = {
        formality: styleValue.formality,
        detail_level: styleValue.detail_level,
        table_preference: styleValue.table_preference,
        diagram_preference: styleValue.diagram_preference,
        mode: styleValue.mode,
      };
      await adapter.saveStyle(enterpriseId, stylePayload);
      message.success("创作风格已保存");
      setStyleOpen(false);
    } catch (err) {
      showGenError(err instanceof Error ? err.message : undefined, "保存风格失败");
    } finally {
      setSavingStyle(false);
    }
  }, [adapter, enterpriseId, styleValue, showGenError]);

  const currentStatus = generating ? "generating" : doc?.status || "empty";
  /** 上次会话中断残留的 generating 行（当前页面没有正在运行的生成） */
  const interruptedGenerating = doc?.status === "generating" && !generating;
  const partialChapterCount = interruptedGenerating
    ? (doc?.chapters ?? []).filter((c) => c.content && c.content.trim()).length
    : 0;
  const currentChapter = selectedDef;
  const hasDraftContent = Object.values(contentByKey).some((c) => c && c.trim());
  const saveStatus = currentChapter ? saveState[currentChapter.key] || "saved" : "saved";

  if (loading) {
    return (
      <div style={{ display: "flex", justifyContent: "center", padding: 80 }}>
        <Spin size="large" tip="正在加载报告..." />
      </div>
    );
  }

  const toolbar = (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, marginBottom: 12, flexWrap: "wrap" }}>
      <Space wrap>
        <Text strong style={{ fontSize: 15 }}>
          {doc?.title || meta.emptyTitle}
        </Text>
        {currentStatus === "completed" && <Tag color="green">已完成</Tag>}
        {currentStatus === "draft" && <Tag color="blue">草稿</Tag>}
        {currentStatus === "generating" && <Tag color="processing">生成中</Tag>}
      </Space>
      <Space wrap>
        {currentStatus === "completed" && (
          <Button
            danger
            icon={<ThunderboltOutlined />}
            onClick={() => { setGenerating(null); void startFullGenerate(); }}
          >
            重新生成
          </Button>
        )}
        {!generating && (
          <Button
            icon={<ThunderboltOutlined />}
            onClick={() => void startFullGenerate()}
            disabled={!!generating}
          >
            一键生成全部
          </Button>
        )}
        {generating === "full" && (
          <Button danger icon={<StopOutlined />} onClick={stopGeneration}>
            停止生成
          </Button>
        )}
        {(currentStatus === "draft" || currentStatus === "generating") && (
          <>
            <Button
              icon={<AuditOutlined />}
              loading={reviewing}
              disabled={!!generating}
              onClick={() => void handleReview()}
            >
              AI 审查
            </Button>
            <Button icon={<SettingOutlined />} disabled={!!generating} onClick={() => void openStyleModal()}>
              创作风格
            </Button>
            <Button
              icon={<SaveOutlined />}
              loading={savingVersion}
              disabled={!!generating}
              onClick={() => void handleSaveVersion()}
            >
              保存版本
            </Button>
            <Button
              type="primary"
              icon={<FileSyncOutlined />}
              loading={merging}
              disabled={!hasDraftContent || !!generating}
              onClick={() => void handleMerge()}
            >
              合并定稿
            </Button>
          </>
        )}
        <Button
          icon={<EyeOutlined />}
          disabled={!!generating}
          onClick={() => navigate(`/enterprises/${enterpriseId}/${kind === "resource" ? "resource-investigation" : "risk-assessment"}/preview`)}
        >
          预览
        </Button>
        <Button
          type="primary"
          icon={<ExportOutlined />}
          loading={exporting}
          onClick={() => {
            setExporting(true);
            adapter
              .download(enterpriseId)
              .catch((err: unknown) =>
                message.error(
                  (err as Error)?.message || "导出失败，请重试",
                ),
              )
              .finally(() => setExporting(false));
          }}
        >
          导出
        </Button>
      </Space>
    </div>
  );

  if (!doc && !generating && !hasDraftContent) {
    return (
      <div>
        {aiUnavailable && <AiNotConfiguredHint onClose={() => setAiUnavailable(false)} />}
        <div style={{ textAlign: "center", padding: "48px 0" }}>
          <Empty
            image={<ThunderboltOutlined style={{ fontSize: 56, color: "#1677ff" }} />}
            description={
              <>
                <Title level={4} style={{ marginBottom: 4 }}>{meta.emptyTitle}</Title>
                <Text type="secondary">{meta.emptyDesc}</Text>
              </>
            }
          >
            <Button
              type="primary"
              size="large"
              icon={<ThunderboltOutlined />}
              loading={generating === "full"}
              onClick={() => void startFullGenerate()}
            >
              {meta.generateLabel}
            </Button>
          </Empty>
        </div>
      </div>
    );
  }

  if (currentStatus === "completed" && doc && !generating) {
    return (
      <div>
        {aiUnavailable && <AiNotConfiguredHint onClose={() => setAiUnavailable(false)} />}
        {toolbar}
        <div style={{ color: "#999", marginBottom: 12 }}>
          生成时间：
          {doc.generatedAt
            ? new Date(doc.generatedAt).toLocaleString("zh-CN")
            : "-"}
        </div>
        <div
          style={{
            background: "#fff",
            padding: 24,
            border: "1px solid #f0f0f0",
            borderRadius: 8,
            maxHeight: "calc(100vh - 320px)",
            overflow: "auto",
            fontFamily: "SimSun, serif",
            fontSize: 15,
            lineHeight: 2,
          }}
        >
          <style>{REPORT_TABLE_STYLE}</style>
          <div
            className="risk-report-content"
            dangerouslySetInnerHTML={{ __html: sanitizeHtml(renderReportMarkdown(doc.content || "")) }}
          />
        </div>
      </div>
    );
  }

  // 草稿/生成中：侧栏 + 编辑器
  const visibleChapters = chapterDefs.length > 0 ? chapterDefs : fallbackChapters;
  return (
    <div>
      {aiUnavailable && <AiNotConfiguredHint onClose={() => setAiUnavailable(false)} />}
      {toolbar}
      {thinkingText && (
        <div style={{ marginBottom: 8, fontSize: 13, color: "#9ca3af", lineHeight: 1.6 }}>
          {thinkingText}<span style={{ color: "#9ca3af" }}>▌</span>
        </div>
      )}
      {interruptedGenerating && (
        <Alert
          type="info"
          showIcon
          style={{ marginBottom: 12 }}
          message="报告正在后台生成中…"
          description={`已保存 ${partialChapterCount}/${chapterDefs.length} 章；生成不会因离开页面而中断，可稍后返回查看`}
          action={
            <Button size="small" onClick={() => void loadDocument()}>
              立即刷新
            </Button>
          }
        />
      )}
      {generating === "full" && (
        <div style={{ marginBottom: 12 }}>
          <Progress
            percent={batchProgress.total > 0 ? Math.round((batchProgress.current / batchProgress.total) * 100) : 0}
            format={() => `${batchProgress.current}/${batchProgress.total}`}
            status="active"
          />
          <div style={{ textAlign: "center", fontSize: 13, color: "#666", marginTop: 4 }}>
            {batchProgress.message}
          </div>
        </div>
      )}
      {failedChapters.length > 0 && !generating && (
        <Alert
          type="warning"
          showIcon
          style={{ marginBottom: 12 }}
          message={`${failedChapters.length} 个章节生成失败`}
          description={failedChapters.map((f) => f.title).join("、")}
          action={
            <Button
              size="small"
              onClick={() => {
                const first = failedChapters[0];
                setFailedChapters([]);
                if (first) {
                  message.info("正在重试第一个失败章节；其余章节可在左侧单独重新生成");
                  runChapterGeneration(first.key, "generate");
                }
              }}
            >
              重试失败章节
            </Button>
          }
        />
      )}
      <div style={{ display: "flex", gap: 16, height: "calc(100vh - 320px)", minHeight: 460 }}>
        {!collapsed && (
          <div style={{ width: 280, flexShrink: 0, border: "1px solid #f0f0f0", borderRadius: 8, overflow: "auto", background: "#fff" }}>
            <div style={{ padding: "10px 12px", fontWeight: 600, fontSize: 13, borderBottom: "1px solid #f0f0f0", background: "#fafafa", color: "#666", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span>报告章节</span>
              <Button type="text" size="small" onClick={() => setCollapsed(true)}>收起</Button>
            </div>
            {visibleChapters.map((c) => {
              const content = contentByKey[c.key] || "";
              const isGen = generatingKeys.has(c.key);
              const failed = failedChapters.some((f) => f.key === c.key);
              const isSelected = selectedKey === c.key;
              return (
                <div
                  key={c.key}
                  onClick={() => selectChapter(c.key)}
                  style={{
                    padding: "10px 12px",
                    cursor: generating && !isGen ? "default" : "pointer",
                    background: isSelected ? "#e6f4ff" : "transparent",
                    borderLeft: isSelected ? "3px solid #1677ff" : "3px solid transparent",
                    borderBottom: "1px solid #f0f0f0",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    {isGen ? (
                      <LoadingOutlined style={{ color: "#1677ff" }} />
                    ) : content ? (
                      <CheckCircleFilled style={{ color: "#52c41a" }} />
                    ) : failed ? (
                      <CloseCircleFilled style={{ color: "#ff4d4f" }} />
                    ) : (
                      <span style={{ width: 14, color: "#d9d9d9" }}>○</span>
                    )}
                    <Text
                      ellipsis={{ tooltip: c.title }}
                      style={{ fontWeight: isSelected ? 600 : 400, color: content || isGen ? "#333" : "#999" }}
                    >
                      {c.title}
                    </Text>
                  </div>
                  <div style={{ marginLeft: 22, fontSize: 12, color: "#999" }}>
                    {isGen ? "AI 生成中..." : content ? `${content.length} 字` : failed ? "生成失败，可重试" : "未生成"}
                  </div>
                </div>
              );
            })}
          </div>
        )}
        {collapsed && (
          <Button type="text" onClick={() => setCollapsed(false)} style={{ flexShrink: 0 }}>
            展开章节
          </Button>
        )}
        <div style={{ flex: 1, display: "flex", flexDirection: "column", background: "#fff", border: "1px solid #f0f0f0", borderRadius: 8, overflow: "hidden", minWidth: 0 }}>
          {currentChapter ? (
            <>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 14px", borderBottom: "1px solid #f0f0f0" }}>
                <Space>
                  <Text strong>{currentChapter.title}</Text>
                  <Badge
                    count={currentChapter ? (contentByKey[currentChapter.key] || "").length : 0}
                    overflowCount={99999}
                    style={{ backgroundColor: "#999" }}
                  />
                </Space>
                <Space size="middle">
                  <ReportChapterActions
                    hasContent={!!(currentChapter && contentByKey[currentChapter.key])}
                    loading={generatingKeys.has(currentChapter.key)}
                    disabled={generating === "full"}
                    generate={() => setGenModalKey(currentChapter.key)}
                    regenerate={() => {
                      Modal.confirm({
                        title: `重新生成「${currentChapter.title}」？`,
                        content: "重新生成将覆盖当前章节内容，完成后可在对比预览中选择接受或拒绝。",
                        okText: "开始生成",
                        onOk: () => runChapterGeneration(currentChapter.key, "regenerate"),
                      });
                    }}
                    stop={stopGeneration}
                  />
                  <span style={{ fontSize: 12, color: saveStatus === "error" ? "#cf1322" : saveStatus === "saving" ? "#1677ff" : "#999" }}>
                    {saveStatus === "saving"
                      ? "保存中..."
                      : saveStatus === "error"
                        ? "保存失败"
                        : saveStatus === "idle"
                          ? "未保存"
                          : "已保存"}
                  </span>
                  {saveStatus === "error" && currentChapter && (
                    <Button
                      type="link"
                      size="small"
                      onClick={() => {
                        // 直接读取当前 state 中的最新内容重试，避免闭包陈旧值
                        setSaveState((prev) => ({ ...prev, [currentChapter.key]: "saving" }));
                        const md = contentByKey[currentChapter.key] || "";
                        void saveOne(currentChapter.key, md);
                      }}
                    >
                      重试保存
                    </Button>
                  )}
                </Space>
              </div>
              <div style={{ flex: 1, overflow: "auto", padding: 14 }}>
                <TiptapEditor
                  content={editorHtml}
                  onChange={(html) => {
                    if (!currentChapter) return;
                    const md = htmlToMarkdown(html);
                    setChapterContent(currentChapter.key, md);
                    // 被生成的章节由生成流程落库，避免编辑回调与 SSE 竞争
                    if (!generatingKeys.has(currentChapter.key)) scheduleSave(currentChapter.key, md);
                  }}
                  readOnly={generating === "full" || generatingKeys.has(currentChapter.key)}
                  placeholder={`编辑「${currentChapter.title}」内容...`}
                />
                {kind === "risk" && currentChapter?.key === "ch2_summary" && (doc?.fourColorImages?.length ?? 0) > 0 && (
                  <div style={{ marginTop: 16 }}>
                    <div style={{ fontWeight: 600, marginBottom: 8 }}>四色分布图</div>
                    {doc?.fourColorImages?.map((im) => (
                      <Card
                        key={im.floor_id}
                        size="small"
                        style={{ marginBottom: 12 }}
                        title={`${im.floor_name} 四色分布图`}
                      >
                        <img src={im.url} alt={im.floor_name} style={{ maxWidth: "100%" }} />
                      </Card>
                    ))}
                  </div>
                )}
              </div>
            </>
          ) : (
            <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 16, color: "#999" }}>
              {generating ? (
                <>
                  <Spin size="large" />
                  <div>正在生成报告章节...</div>
                </>
              ) : (
                <>
                  <ThunderboltOutlined style={{ fontSize: 48, color: "#d9d9d9" }} />
                  <div>从左侧选择一个章节开始编辑，或一键生成全部</div>
                  <Button type="primary" icon={<ThunderboltOutlined />} onClick={() => void startFullGenerate()}>
                    {meta.generateLabel}
                  </Button>
                </>
              )}
            </div>
          )}
        </div>
      </div>

      {/* 创作风格 */}
      <Modal
        title="创作风格"
        open={styleOpen}
        onCancel={() => setStyleOpen(false)}
        width={560}
        onOk={() => void saveStyle()}
        okText="保存风格"
        confirmLoading={savingStyle}
      >
        <StylePanel value={styleValue} onChange={setStyleValue} />
      </Modal>

      {/* 审查 */}
      <ReviewDrawer
        open={reviewOpen}
        issues={reviewIssues}
        onClose={() => {
          setReviewOpen(false);
          setReviewIssues([]);
        }}
        onApply={(keys) => void applyReview(keys)}
        applying={applyingReview}
        chapterTitleMap={chapterTitleMap}
      />

      {/* 修订 diff（逐条确认） */}
      {diffIndex >= 0 && diffQueue[diffIndex] && (
        <DiffPreviewModal
          open={diffIndex >= 0}
          oldText={renderReportMarkdown(diffQueue[diffIndex].original)}
          newText={renderReportMarkdown(diffQueue[diffIndex].revised)}
          onAccept={() => closeDiff(true)}
          onReject={() => closeDiff(false)}
          onClose={() => closeDiff(false)}
        />
      )}

      {/* 单章生成自定义指令 */}
      <Modal
        title="生成本章"
        open={!!genModalKey}
        onCancel={() => setGenModalKey(null)}
        onOk={() => {
          if (!genModalKey) return;
          runChapterGeneration(genModalKey, "generate");
          setGenModalKey(null);
        }}
        okText="开始生成"
        width={560}
      >
        <Text type="secondary">
          AI 将按当前章节定义与创作风格生成内容，生成期间可随时停止。
        </Text>
      </Modal>
    </div>
  );
}

const REPORT_TABLE_STYLE = `
  .risk-report-content table {
    border-collapse: collapse;
    width: 100%;
    margin: 12px 0;
    font-size: 13px;
  }
  .risk-report-content table th,
  .risk-report-content table td {
    border: 1px solid #333;
    padding: 6px 10px;
    text-align: left;
    vertical-align: top;
  }
  .risk-report-content table th {
